import unittest
from solution import dependency_order

class VisibleTests(unittest.TestCase):
    def test_newly_ready_task_reorders_queue(self):
        self.assertEqual(dependency_order({"a": [], "b": ["a"], "z": []}), ["a", "b", "z"])

    def test_chain(self):
        self.assertEqual(dependency_order({"deploy": ["test"], "test": ["build"], "build": []}), ["build", "test", "deploy"])

    def test_cycle(self):
        with self.assertRaises(ValueError):
            dependency_order({"a": ["b"], "b": ["a"]})

