import unittest
from solution import dependency_order

class HiddenTests(unittest.TestCase):
    def test_reference_only_and_duplicate_dependencies(self):
        self.assertEqual(dependency_order({"c": ["a", "a"], "b": ["a"]}), ["a", "b", "c"])

    def test_diamond_and_multiple_ready_steps(self):
        graph = {"a": [], "b": ["a"], "c": ["a"], "d": ["b", "c"], "z": []}
        self.assertEqual(dependency_order(graph), ["a", "b", "c", "d", "z"])

    def test_disconnected_cycle_and_self_cycle(self):
        for graph in ({"ready": [], "x": ["y"], "y": ["x"]}, {"x": ["x"]}):
            with self.subTest(graph=graph), self.assertRaises(ValueError):
                dependency_order(graph)

    def test_empty_and_no_mutation(self):
        self.assertEqual(dependency_order({}), [])
        graph = {"a": [], "b": ["a", "a"]}
        self.assertEqual(dependency_order(graph), ["a", "b"])
        self.assertEqual(graph, {"a": [], "b": ["a", "a"]})
